            return 'C'
        return 'D'

    # Endgame: last few rounds, defect if profitable
    remaining = 100 - n
    if remaining <= 3:
        if opp_c > opp_d:
            return 'D'
        return 'D'

    # Default: cooperate if opponent mostly cooperates
    if opp_c >= opp_d:
        return 'C'
    else:
        # occasional forgiveness
        if rng.random() < 0.1:
            return 'C'
        return 'D'
